      // Extract YouTube ID if present
      const getYouTubeId = (url: string) => {
        const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
        const match = url.match(regExp);
        return (match && match[2].length === 11) ? match[2] : null;
      };

      const youtubeId = getYouTubeId(block.content);

      return (
        <div className="mb-12">
          {block.title && <h3 className="text-2xl font-bold mb-4 text-slate-900">{block.title}</h3>}
          <div className="aspect-video rounded-2xl overflow-hidden shadow-lg bg-black">
            {youtubeId ? (
              <iframe
                className="w-full h-full"
                src={`https://www.youtube.com/embed/${youtubeId}`}
                title={block.title || "YouTube video player"}
                frameBorder="0"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                allowFullScreen
              ></iframe>
            ) : (
              <video controls className="w-full h-full" src={block.content}>
                Your browser does not support the video tag.
              </video>
            )}
          </div>
          {block.caption && <p className="text-sm text-slate-500 mt-2 text-center italic">{block.caption}</p>}
        </div>
      );
    case 'figma':
      return (
        <div className="mb-12">
           {block.title && <h3 className="text-2xl font-bold mb-4 text-slate-900">{block.title}</h3>}
           <div className="w-full h-[600px] bg-slate-100 rounded-2xl border border-slate-200 flex flex-col items-center justify-center p-8 text-center">
