              <ExternalLink className="text-slate-400 mb-2" size={48} />
              <p className="text-sm text-slate-400 max-w-md">I en riktig produktion skulle detta vara en `iframe` till Figma-prototypen. Eftersom vi inte har en faktisk embed-länk här visas denna platshållare.</p>
              <a href={block.content} target="_blank" rel="noreferrer" className="mt-4 text-brand-600 hover:underline">Öppna i Figma</a>
           </div>
           {block.caption && <p className="text-sm text-slate-500 mt-2 text-center italic">{block.caption}</p>}
        </div>
      );
    default:
