            </div>
            {block.caption && <p className="text-sm text-slate-500 mt-2 text-center italic">{block.caption}</p>}
          </div>
        );
      } else if (isYoutube) {
         // Fallback link if we can't extract ID but it looks like YouTube
         return (
          <div className="mb-12">
            {block.title && <h3 className="text-2xl font-bold mb-4 text-slate-900">{block.title}</h3>}
            <div className="p-6 bg-slate-50 rounded-2xl border border-slate-200 text-center">
               <p className="text-slate-600 mb-2">Videospelaren kunde inte laddas.</p>
               <a href={block.content} target="_blank" rel="noreferrer" className="text-brand-600 font-bold hover:underline flex items-center justify-center gap-2">
