      // Fallback for non-YouTube videos (standard MP4 etc)
      return (
        <div className="mb-12">
          {block.title && <h3 className="text-2xl font-bold mb-4 text-slate-900">{block.title}</h3>}
          <div className="aspect-video rounded-2xl overflow-hidden shadow-lg bg-black">
            <video controls className="w-full h-full" src={block.content}>
              Your browser does not support the video tag.
            </video>
          </div>
          {block.caption && <p className="text-sm text-slate-500 mt-2 text-center italic">{block.caption}</p>}
        </div>
      );

    case 'web':
      return (
        <div className="mb-12">
          {block.title && <h3 className="text-2xl font-bold mb-4 text-slate-900">{block.title}</h3>}
          <div className="w-full h-[700px] rounded-3xl overflow-hidden shadow-2xl border-4 border-slate-900 bg-slate-100 relative">
