const BackgroundBlobs = () => (
  <div className="fixed inset-0 z-[-1] overflow-hidden pointer-events-none bg-slate-50/50 dark:bg-slate-950 transition-colors duration-300">
    <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[1000px] h-[1000px] bg-blue-100/40 dark:bg-blue-900/10 rounded-full blur-[100px] opacity-60 mix-blend-multiply dark:mix-blend-screen animate-pulse" style={{ animationDuration: '8s' }} />
    <div className="absolute top-[20%] right-[-20%] w-[800px] h-[800px] bg-purple-100/40 dark:bg-purple-900/10 rounded-full blur-[100px] opacity-60 mix-blend-multiply dark:mix-blend-screen" />
    <div className="absolute bottom-[-10%] left-[-10%] w-[600px] h-[600px] bg-teal-100/30 dark:bg-teal-900/10 rounded-full blur-[80px] opacity-50 mix-blend-multiply dark:mix-blend-screen" />
    {/* Noise overlay for texture */}
    <div className="absolute inset-0 opacity-[0.015] dark:opacity-[0.03]" style={{ backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E")` }}></div>
  </div>
);

const App: React.FC = () => {
  const [isDark, setIsDark] = useState(false);

  useEffect(() => {
    // Check local storage or system preference
    const storedTheme = localStorage.getItem('theme');
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (storedTheme === 'dark' || (!storedTheme && prefersDark)) {
      setIsDark(true);
      document.documentElement.classList.add('dark');
    } else {
      setIsDark(false);
      document.documentElement.classList.remove('dark');
    }
  }, []);

  const toggleTheme = () => {
    if (isDark) {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
      setIsDark(false);
    } else {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
      setIsDark(true);
    }
  };

  return (
    <Router>
      <ScrollToTop />
      <div className="min-h-screen flex flex-col pt-32 font-sans relative selection:bg-brand-200 selection:text-brand-900 dark:selection:bg-brand-900 dark:selection:text-brand-100 transition-colors duration-300">
        <BackgroundBlobs />
        <Navigation isDark={isDark} toggleTheme={toggleTheme} />

        <main className="flex-grow relative z-10">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/about" element={<About />} />
            <Route path="/contact" element={<Contact />} />
            <Route path="/project/:id" element={<React.Fragment><Home /><div className="fixed inset-0 bg-white/0 z-50 overflow-y-auto"><ProjectDetail /></div></React.Fragment>} /> 
          </Routes>
        </main>

        <ContactCTA />
        <Footer />
        <AIAssistant />
      </div>
    </Router>
  );
};

