import { HashRouter as Router, Routes, Route, useLocation, Link } from 'react-router-dom';
import Home from './components/Home';
import ProjectDetail from './components/ProjectDetail';
import About from './components/About';
import Contact from './components/Contact';
import AIAssistant from './components/AIAssistant';
import ContactCTA from './components/ContactCTA';
import { PROFILE } from './constants';
import { motion } from 'framer-motion';
import { Sun, Moon } from 'lucide-react';

const ScrollToTop = () => {
  const { pathname } = useLocation();
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
};

const NavLink = ({ to, children }: { to: string; children: React.ReactNode }) => {
  const location = useLocation();
  const isActive = location.pathname === to || (to !== '/' && location.pathname.startsWith(to));

  return (
    <Link 
      to={to} 
      className={`relative px-4 py-2 rounded-full text-sm font-medium transition-all duration-300 ${
        isActive 
          ? 'text-white' 
          : 'text-slate-400 hover:text-slate-200'
      }`}
    >
      {isActive && (
        <motion.span
          layoutId="nav-pill"
          className="absolute -bottom-1 left-4 right-4 h-0.5 bg-white rounded-full"
          initial={false}
          transition={{ type: "spring", stiffness: 300, damping: 30 }}
        />
      )}
      <span className="relative z-10">{children}</span>
    </Link>
  );
};

const Navigation = ({ isDark, toggleTheme }: { isDark: boolean; toggleTheme: () => void }) => {
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <motion.nav 
      initial={{ y: -100, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.6, ease: "easeOut" }}
      className={`fixed top-0 left-0 right-0 z-40 transition-all duration-300 ${
        isScrolled 
          ? 'bg-black/80 backdrop-blur-md border-b border-white/10 py-4 shadow-sm' 
          : 'bg-transparent py-6'
      }`}
    >
      <div className="max-w-7xl mx-auto px-6 md:px-12 flex items-center justify-between">
        <Link to="/" className="flex items-center gap-2 group">
          <img 
            src={PROFILE.logo} 
            alt="Nisse Lindberg Logo" 
            className="h-8 w-auto object-contain transition-transform group-hover:scale-105 invert brightness-200" 
          />
        </Link>

        <div className="flex items-center gap-6">
          <div className="flex items-center gap-2">
            <NavLink to="/">Work</NavLink>
            <NavLink to="/about">About</NavLink>
            <NavLink to="/contact">Contact</NavLink>
          </div>

          <div className="h-6 w-px bg-white/10 mx-2"></div>

          <button 
            onClick={toggleTheme}
            className="p-2 rounded-full hover:bg-white/10 text-slate-400 hover:text-white transition-colors"
            aria-label="Toggle Dark Mode"
          >
            {isDark ? <Sun size={20} /> : <Moon size={20} />}
          </button>
        </div>
      </div>
    </motion.nav>
  );
};

const Footer = () => (
  <footer className="relative z-10 bg-black/50 border-t border-white/5 py-12 px-6 text-center backdrop-blur-sm transition-colors duration-300">
    <div className="flex justify-center items-center gap-4 mb-4">
       <img src={PROFILE.logo} className="h-10 opacity-30 invert brightness-200 hover:opacity-100 transition-all" alt="Logo" />
    </div>
    <p className="text-slate-600 text-sm font-medium">© {new Date().getFullYear()} {PROFILE.name}. Crafted with focus.</p>
  </footer>
);

const BackgroundBlobs = () => (
  <div className="fixed inset-0 z-[-1] overflow-hidden pointer-events-none bg-black transition-colors duration-300">
    <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[1200px] h-[1200px] bg-blue-900/20 rounded-full blur-[120px] opacity-40 mix-blend-screen animate-pulse" style={{ animationDuration: '10s' }} />
    <div className="absolute top-[20%] right-[-10%] w-[800px] h-[800px] bg-purple-900/20 rounded-full blur-[100px] opacity-30 mix-blend-screen" />
    <div className="absolute bottom-[-10%] left-[-10%] w-[900px] h-[900px] bg-teal-900/10 rounded-full blur-[120px] opacity-30 mix-blend-screen" />
    {/* Noise overlay for texture */}
    <div className="absolute inset-0 opacity-[0.05]" style={{ backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E")` }}></div>
  </div>
);

const App: React.FC = () => {
  const [isDark, setIsDark] = useState(true); // Default to True (Dark)

  useEffect(() => {
    // Check local storage or system preference, default to dark if not set
    const storedTheme = localStorage.getItem('theme');

    if (storedTheme === 'light') {
      setIsDark(false);
      document.documentElement.classList.remove('dark');
    } else {
      setIsDark(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  const toggleTheme = () => {
    if (isDark) {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
      setIsDark(false);
    } else {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
      setIsDark(true);
    }
  };

  return (
    <Router>
      <ScrollToTop />
      <div className="min-h-screen flex flex-col pt-32 font-sans relative selection:bg-brand-900 selection:text-brand-100 transition-colors duration-300 bg-black text-slate-100">
        <BackgroundBlobs />
        <Navigation isDark={isDark} toggleTheme={toggleTheme} />

        <main className="flex-grow relative z-10">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/about" element={<About />} />
            <Route path="/contact" element={<Contact />} />
            <Route path="/project/:id" element={<React.Fragment><Home /><div className="fixed inset-0 bg-black/50 z-50 overflow-y-auto backdrop-blur-sm"><ProjectDetail /></div></React.Fragment>} /> 
          </Routes>
        </main>

        <ContactCTA />
        <Footer />
        <AIAssistant />
      </div>
    </Router>
  );
};

export default App;

