import React, { useEffect } from 'react';
import { PROJECTS } from '../constants';
import { Project, ContentBlock } from '../types';
import { ArrowLeft, Clock, Users, Wrench, ExternalLink } from 'lucide-react';
import { motion } from 'framer-motion';
import { Link, useParams, useNavigate } from 'react-router-dom';
import ContactCTA from './ContactCTA';

const ContentRenderer: React.FC<{ block: ContentBlock }> = ({ block }) => {
  switch (block.type) {
    case 'text':
      return (
        <div className="mb-12">
          {block.title && <h3 className="font-display text-2xl font-bold mb-4 text-white">{block.title}</h3>}
          <p className="text-lg text-slate-300 leading-relaxed whitespace-pre-wrap">{block.content}</p>
        </div>
      );
    case 'image':
      return (
        <div className="mb-12">
          <img src={block.content} alt={block.caption || 'Project image'} className="w-full rounded-2xl shadow-md border border-white/5" />
          {block.caption && <p className="text-sm text-slate-500 mt-2 text-center italic">{block.caption}</p>}
        </div>
      );
    case 'video':
      const getYouTubeId = (url: string) => {
        if (!url) return null;
        try {
          const urlObj = new URL(url.trim());
          if (urlObj.hostname === 'youtu.be') {
            return urlObj.pathname.slice(1);
          }
          if (urlObj.hostname.includes('youtube.com')) {
            if (urlObj.searchParams.has('v')) {
              return urlObj.searchParams.get('v');
            }
            if (urlObj.pathname.startsWith('/embed/')) {
              return urlObj.pathname.split('/')[2];
            }
            if (urlObj.pathname.startsWith('/v/')) {
               return urlObj.pathname.split('/')[2];
            }
          }
        } catch (e) {
          // Fallback if URL parsing fails
        }

        // Fallback regex for non-standard URLs
        const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
        const match = url.trim().match(regExp);
        return (match && match[2].length === 11) ? match[2] : null;
      };

      const youtubeId = getYouTubeId(block.content);
      const isYoutube = block.content.includes('youtube') || block.content.includes('youtu.be');

      if (youtubeId) {
        return (
          <div className="mb-12">
            {block.title && <h3 className="font-display text-2xl font-bold mb-4 text-white">{block.title}</h3>}
            <div className="aspect-video rounded-2xl overflow-hidden shadow-lg bg-black relative border border-white/5">
              <iframe
                className="absolute top-0 left-0 w-full h-full"
                src={`https://www.youtube.com/embed/${youtubeId}?rel=0`}
                title={block.title || "YouTube video player"}
                frameBorder="0"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                allowFullScreen
              ></iframe>
            </div>
            {block.caption && <p className="text-sm text-slate-500 mt-2 text-center italic">{block.caption}</p>}
          </div>
        );
      } else if (isYoutube) {
         // Fallback link
         return (
          <div className="mb-12">
            {block.title && <h3 className="font-display text-2xl font-bold mb-4 text-white">{block.title}</h3>}
            <div className="p-6 bg-slate-900/50 rounded-2xl border border-slate-800 text-center">
               <p className="text-slate-400 mb-2">Videospelaren kunde inte laddas.</p>
               <a href={block.content} target="_blank" rel="noreferrer" className="text-brand-400 font-bold hover:underline flex items-center justify-center gap-2">
                 Se videon på YouTube <ExternalLink size={16} />
               </a>
            </div>
            {block.caption && <p className="text-sm text-slate-500 mt-2 text-center italic">{block.caption}</p>}
          </div>
         );
      }

      // Fallback for non-YouTube videos
      return (
        <div className="mb-12">
          {block.title && <h3 className="font-display text-2xl font-bold mb-4 text-white">{block.title}</h3>}
          <div className="aspect-video rounded-2xl overflow-hidden shadow-lg bg-black border border-white/5">
            <video controls className="w-full h-full" src={block.content}>
              Your browser does not support the video tag.
            </video>
          </div>
          {block.caption && <p className="text-sm text-slate-500 mt-2 text-center italic">{block.caption}</p>}
        </div>
      );

    case 'web':
      return (
        <div className="mb-12">
          {block.title && <h3 className="font-display text-2xl font-bold mb-4 text-white">{block.title}</h3>}
          <div className="w-full h-[700px] rounded-3xl overflow-hidden shadow-2xl border-4 border-slate-800 bg-slate-900 relative">
             <div className="absolute top-0 left-0 right-0 h-8 bg-slate-900 flex items-center px-4 gap-2 border-b border-slate-800">
                <div className="w-3 h-3 rounded-full bg-red-500"></div>
                <div className="w-3 h-3 rounded-full bg-yellow-500"></div>
                <div className="w-3 h-3 rounded-full bg-green-500"></div>
             </div>
             <iframe
               src={block.content}
               className="w-full h-full pt-8 bg-white"
               title={block.title || "Live App Preview"}
             />
          </div>
          <div className="flex justify-center mt-4">
             <a href={block.content} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 text-brand-400 font-bold hover:text-brand-300 transition-colors">
               Öppna appen i nytt fönster <ExternalLink size={18} />
             </a>
          </div>
          {block.caption && <p className="text-sm text-slate-500 mt-2 text-center italic">{block.caption}</p>}
        </div>
      );
    case 'figma':
      const figmaEmbedUrl = `https://www.figma.com/embed?embed_host=share&url=${encodeURIComponent(block.content)}`;
      return (
        <div className="mb-12">
           {block.title && <h3 className="font-display text-2xl font-bold mb-4 text-white">{block.title}</h3>}
           <div className="w-full h-[600px] bg-slate-900 rounded-2xl border border-slate-800 overflow-hidden shadow-sm relative">
              <iframe
                className="absolute top-0 left-0 w-full h-full border-0"
                src={figmaEmbedUrl}
                title={block.title || "Figma Prototype"}
                allowFullScreen
              ></iframe>
           </div>
           <div className="flex justify-center mt-4">
               <a href={block.content} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 text-brand-400 font-bold hover:text-brand-300 transition-colors">
                 Öppna i helskärm (Figma) <ExternalLink size={18} />
               </a>
           </div>
           {block.caption && <p className="text-sm text-slate-500 mt-2 text-center italic">{block.caption}</p>}
        </div>
      );
    default:
      return null;
  }
};

