                         </div>
                         <div className={`${fontFamilyStyle}`}>
                            <p className="text-5xl mb-4 text-zinc-900 dark:text-white">Aa</p>
                            <p className="text-sm text-zinc-500 leading-relaxed">
                              ABCDEFGHIJKLMNOPQRSTUVWXYZ<br/>
                              abcdefghijklmnopqrstuvwxyz<br/>
                              1234567890
                            </p>
                         </div>
                      </div>
                    );
                  })}
                </div>
             </div>
           </div>
        </div>
      );

    case 'web':
      return (
        <div className="mb-12">
          {block.title && <h3 className="text-2xl font-bold mb-4 text-zinc-900 dark:text-white">{block.title}</h3>}
          {/* Increased height to 85vh for a "fullsize" feel */}
          <div className="w-full h-[85vh] min-h-[600px] rounded-3xl overflow-hidden shadow-2xl border-4 border-zinc-900 dark:border-zinc-800 bg-zinc-100 dark:bg-zinc-900 relative">
             <div className="absolute top-0 left-0 right-0 h-8 bg-zinc-200 dark:bg-zinc-900 flex items-center px-4 gap-2 border-b border-zinc-300 dark:border-zinc-800">
