      return (
        <div className="mb-6">
          {block.title && <h3 className="text-xl font-bold mb-3 text-zinc-900 dark:text-white">{block.title}</h3>}
          <a 
            href={block.content} 
            target="_blank" 
            rel="noreferrer" 
            className="group block p-6 bg-zinc-50 dark:bg-zinc-900/50 border border-zinc-200 dark:border-zinc-800 rounded-2xl hover:bg-brand-50 dark:hover:bg-brand-900/10 hover:border-brand-200 dark:hover:border-brand-800 transition-all shadow-sm hover:shadow-md"
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                 <div className="bg-white dark:bg-zinc-800 p-3 rounded-full shadow-sm text-brand-600 dark:text-brand-400">
                    <LinkIcon size={24} />
