                  className="absolute top-0 left-0 w-full h-full"
                  src={`https://www.youtube.com/embed/${youtubeId}?autoplay=1&mute=1&loop=1&playlist=${youtubeId}&controls=0&playsinline=1&rel=0`}
                  title={block.title || "YouTube video player"}
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                  referrerPolicy="no-referrer" 
                ></iframe>
              </div>
              {block.caption && <p className="text-base text-zinc-500 mt-4 text-center italic">{block.caption}</p>}
            </div>
          </StandardWrapper>
        );
      } else if (isYoutube) {
         return (
          <StandardWrapper>
            <div className="p-8 bg-zinc-50 dark:bg-zinc-900/50 rounded-3xl border border-zinc-200 dark:border-zinc-800 text-center">
