                 Se videon på YouTube <ExternalLink size={20} />
               </a>
            </div>
          </StandardWrapper>
         );
      }

      return (
        <StandardWrapper>
          <div className="w-full">
            {block.title && <h3 className="text-3xl font-bold mb-6 text-zinc-900 dark:text-white">{block.title}</h3>}
