           {block.title && <h3 className="text-3xl font-bold mb-8 text-zinc-900 dark:text-white">{block.title}</h3>}

           <div className="bg-zinc-50 dark:bg-zinc-900/50 rounded-[2rem] p-10 border border-zinc-200 dark:border-zinc-800">
             {/* Colors */}
