                           <span className="text-xs bg-zinc-100 dark:bg-zinc-700 px-3 py-1 rounded-full text-zinc-500">{font.usage}</span>
                         </div>
                         <div className={`${fontFamilyStyle}`}>
                            <p className="text-6xl mb-6 text-zinc-900 dark:text-white">Aa</p>
                            <p className="text-base text-zinc-500 leading-relaxed">
                              ABCDEFGHIJKLMNOPQRSTUVWXYZ<br/>
                              abcdefghijklmnopqrstuvwxyz<br/>
                              1234567890
                            </p>
                         </div>
                      </div>
                    );
                  })}
                </div>
             </div>
           </div>
        </StandardWrapper>
      );

    case 'web':
      return (
        <WideWrapper>
          {block.title && <h3 className="text-3xl font-bold text-zinc-900 dark:text-white mb-6">{block.title}</h3>}
