              target="_blank" 
              rel="noreferrer" 
              className="group block p-8 bg-zinc-50 dark:bg-zinc-900/50 border border-zinc-200 dark:border-zinc-800 rounded-3xl hover:bg-brand-50 dark:hover:bg-brand-900/10 hover:border-brand-200 dark:hover:border-brand-800 transition-all shadow-sm hover:shadow-xl hover:-translate-y-1"
            >
