                      {block.caption || "Öppna länk"}
                    </span>
                    <span className="text-sm text-zinc-400 font-mono mt-1 block truncate max-w-[200px] md:max-w-md">{block.content}</span>
                  </div>
                </div>
                <ExternalLink className="text-zinc-300 group-hover:text-brand-500 transition-colors" size={24} />
              </div>
            </a>
          </div>
        </StandardWrapper>
      );

    case 'figma':
      const figmaEmbedUrl = `https://www.figma.com/embed?embed_host=share&url=${encodeURIComponent(block.content)}&scaling=scale-down-width`;
      return (
