              <NavLink to="/about" onClick={() => setIsMobileMenuOpen(false)}>{t('nav_about')}</NavLink>
              <NavLink to="/contact" onClick={() => setIsMobileMenuOpen(false)}>{t('nav_contact')}</NavLink>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </motion.nav>
  );
};

