                           <span className="text-xs bg-zinc-100 dark:bg-zinc-700 px-3 py-1 rounded-full text-zinc-500 whitespace-nowrap">{font.usage}</span>
                         </div>
                         <div className={`${fontFamilyStyle}`}>
