import React, { useEffect, useState } from 'react';

const CustomCursor: React.FC = () => {
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isHovering, setIsHovering] = useState(false);

  useEffect(() => {
    const onMouseMove = (e: MouseEvent) => {
      setPosition({ x: e.clientX, y: e.clientY });

      const target = e.target as HTMLElement;
      const isClickable = target.closest('button, a, .clickable');
      setIsHovering(!!isClickable);
    };

    window.addEventListener('mousemove', onMouseMove);
    return () => window.removeEventListener('mousemove', onMouseMove);
  }, []);

  return (
    <div 
      className={`custom-cursor ${isHovering ? 'cursor-hover' : ''}`}
      style={{ left: `${position.x}px`, top: `${position.y}px` }}
    />
  );
};

export default CustomCursor;

import React, { useEffect, useState } from 'react';
import { HashRouter as Router, Routes, Route, useLocation, Link } from 'react-router-dom';
import Home from './components/Home';
import ProjectDetail from './components/ProjectDetail';
import About from './components/About';
import Contact from './components/Contact';
import WorkListing from './components/WorkListing';
import AIAssistant from './components/AIAssistant';
import ContactCTA from './components/ContactCTA';
import Footer from './components/Footer';
import CustomCursor from './components/CustomCursor';
import { motion, AnimatePresence } from 'framer-motion';
import { Sun, Moon, Menu, X } from 'lucide-react';
import { LanguageProvider, useLanguage } from './contexts/LanguageContext';

const ScrollToTop = () => {
  const { pathname } = useLocation();
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
};

const Navigation = ({ isDark, toggleTheme }: { isDark: boolean; toggleTheme: () => void }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const { t, language, toggleLanguage, profile } = useLanguage();
  const location = useLocation();

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => { setIsMenuOpen(false); }, [location.pathname]);

  return (
    <>
      <nav className={`fixed top-0 left-0 right-0 z-[100] transition-all duration-500 flex items-center justify-between px-6 md:px-12 py-8 ${isScrolled ? 'bg-white/90 dark:bg-black/90 backdrop-blur-md py-6' : ''}`}>
        <Link to="/" className="relative z-[110] transition-transform hover:scale-105">
          <img src={profile.logo} alt="Logo" className="h-10 md:h-14 w-auto dark:invert" />
        </Link>

        <div className="flex items-center gap-6 relative z-[110]">
          <button onClick={toggleTheme} className="p-2 hover:scale-110 transition-transform">
            {isDark ? <Sun size={24} /> : <Moon size={24} />}
          </button>
          <button onClick={() => setIsMenuOpen(!isMenuOpen)} className="p-2 group">
            {isMenuOpen ? <X size={32} /> : <Menu size={32} className="group-hover:rotate-180 transition-transform duration-500" />}
          </button>
        </div>
      </nav>

      <AnimatePresence>
        {isMenuOpen && (
          <motion.div 
            initial={{ opacity: 0, x: '100%' }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: '100%' }}
            transition={{ type: "spring", damping: 25, stiffness: 200 }}
            className="fixed inset-0 bg-white dark:bg-black z-[105] flex flex-col items-center justify-center gap-8"
          >
            <div className="flex flex-col items-center gap-6">
              <Link to="/" className="text-5xl md:text-7xl font-bold hover:italic transition-all">{t('nav_start')}</Link>
              <Link to="/work" className="text-5xl md:text-7xl font-bold hover:italic transition-all">Work</Link>
              <Link to="/about" className="text-5xl md:text-7xl font-bold hover:italic transition-all">{t('nav_about')}</Link>
              <Link to="/contact" className="text-5xl md:text-7xl font-bold hover:italic transition-all">{t('nav_contact')}</Link>
            </div>

            <button onClick={toggleLanguage} className="mt-12 text-xl font-bold border-b-2 border-black dark:border-white">
              {language === 'sv' ? 'EN' : 'SV'}
            </button>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
};

const AppContent: React.FC = () => {
  const [isDark, setIsDark] = useState(true);

  useEffect(() => {
    const storedTheme = localStorage.getItem('theme');
    if (storedTheme === 'light') {
      setIsDark(false);
      document.documentElement.classList.remove('dark');
    } else {
      setIsDark(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  const toggleTheme = () => {
    const newDark = !isDark;
    setIsDark(newDark);
    document.documentElement.classList.toggle('dark');
    localStorage.setItem('theme', newDark ? 'dark' : 'light');
  };

  return (
    <Router>
      <ScrollToTop />
      <div className="min-h-screen bg-white dark:bg-black text-black dark:text-white selection:bg-black selection:text-white dark:selection:bg-white dark:selection:text-black transition-colors duration-500 font-sans">
        <CustomCursor />
        <Navigation isDark={isDark} toggleTheme={toggleTheme} />

        <main className="pt-32">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/work" element={<WorkListing />} />
            <Route path="/about" element={<About />} />
            <Route path="/contact" element={<Contact />} />
            <Route path="/project/:id" element={
              <React.Fragment>
                <WorkListing />
                <div className="fixed inset-0 bg-black/50 dark:bg-white/10 z-[150] overflow-y-auto backdrop-blur-xl overscroll-contain">
                  <ProjectDetail />
                </div>
              </React.Fragment>
            } /> 
          </Routes>
        </main>

        <ContactCTA />
        <Footer />
        <AIAssistant />
      </div>
    </Router>
  );
};

const App: React.FC = () => (
  <LanguageProvider>
    <AppContent />
  </LanguageProvider>
);

export default App;

