import React from 'react';
import { Project } from '../types';
import { ArrowUpRight } from 'lucide-react';
import { Link } from 'react-router-dom';
import { motion, useMotionValue, useSpring, useTransform } from 'framer-motion';

interface ProjectCardProps {
  project: Project;
  large?: boolean;
}

const ProjectCard: React.FC<ProjectCardProps> = ({ project, large }) => {
  const x = useMotionValue(0);
  const y = useMotionValue(0);

  const mouseXSpring = useSpring(x);
  const mouseYSpring = useSpring(y);

  const rotateX = useTransform(mouseYSpring, [-0.5, 0.5], ["5deg", "-5deg"]);
  const rotateY = useTransform(mouseXSpring, [-0.5, 0.5], ["-5deg", "5deg"]);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const width = rect.width;
    const height = rect.height;
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    const xPct = mouseX / width - 0.5;
    const yPct = mouseY / height - 0.5;
    x.set(xPct);
    y.set(yPct);
  };

  const handleMouseLeave = () => {
    x.set(0);
    y.set(0);
  };

  return (
    <motion.div 
      className="group relative flex flex-col"
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      style={{ rotateX, rotateY, transformStyle: "preserve-3d" }}
    >
      <Link to={`/project/${project.id}`} className="block">
        <div className={`overflow-hidden rounded-[4rem] bg-zinc-50 dark:bg-zinc-900 border border-black/5 dark:border-white/5 transition-all duration-700 ${large ? 'aspect-[21/10]' : 'aspect-[16/12]'}`}>
          <img 
            src={project.thumbnail} 
            alt={project.title} 
            className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-1000 group-hover:scale-[1.05]"
          />

          {/* Elegant Circular Arrow */}
          <div className="absolute top-10 right-10 w-16 h-16 bg-white dark:bg-black rounded-full flex items-center justify-center border border-black/10 dark:border-white/20 opacity-0 group-hover:opacity-100 transition-opacity duration-300 shadow-xl">
             <ArrowUpRight size={24} className="text-black dark:text-white" />
          </div>
        </div>

        <div className="mt-10 px-4 flex justify-between items-start">
          <div className="max-w-md">
            <h3 className="text-4xl font-bold tracking-tighter mb-4 group-hover:italic transition-all">
              {project.title}
            </h3>
            <p className="text-lg font-light opacity-50 leading-relaxed line-clamp-2">
              {project.summary}
            </p>
          </div>
          <div className="text-right">
             <span className="text-[10px] font-bold tracking-[0.4em] uppercase opacity-40 border-2 border-black/10 dark:border-white/20 px-4 py-2 rounded-full">
              {project.category}
            </span>
          </div>
        </div>
      </Link>
    </motion.div>
  );
};

export default ProjectCard;

