  return (
    <>
      <nav className={`fixed top-0 left-0 right-0 z-[100] transition-all duration-700 flex items-center justify-between px-6 md:px-12 py-10 ${isScrolled ? 'backdrop-blur-sm py-6' : ''}`}>
