              <Link to="/about" className="text-5xl md:text-[10vw] font-bold tracking-tighter hover:italic transition-all">{t('nav_about')}</Link>
              <Link to="/contact" className="text-5xl md:text-[10vw] font-bold tracking-tighter hover:italic transition-all">{t('nav_contact')}</Link>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
};

