import { Sun, Moon, Menu, X } from 'lucide-react';
import { LanguageProvider, useLanguage } from './contexts/LanguageContext';

const ScrollToTop = () => {
  const { pathname } = useLocation();
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
};

const Navigation = ({ isDark, toggleTheme }: { isDark: boolean; toggleTheme: () => void }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const { t, language, toggleLanguage, profile } = useLanguage();
  const location = useLocation();

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => { setIsMenuOpen(false); }, [location.pathname]);

  // Lås scroll när menyn är öppen
  useEffect(() => {
    if (isMenuOpen) document.body.style.overflow = 'hidden';
    else document.body.style.overflow = '';
  }, [isMenuOpen]);

  return (
    <>
      <nav className={`fixed top-0 left-0 right-0 z-[100] transition-all duration-700 flex items-center justify-between px-6 md:px-12 py-10 ${isScrolled ? 'backdrop-blur-sm py-6' : ''}`}>
        <Link to="/" className="relative z-[110] flex items-center gap-4 group">
          <img src={profile.logo} alt="Logo" className="h-10 md:h-12 w-auto dark:invert transition-transform group-hover:scale-105" />
          <span className="text-[10px] font-bold tracking-[0.4em] uppercase opacity-20 group-hover:opacity-100 transition-opacity hidden md:block">Nisse Lindberg</span>
        </Link>

        <div className="flex items-center gap-6 md:gap-10 relative z-[110]">
          <button onClick={toggleLanguage} className="text-[10px] font-bold tracking-widest opacity-40 hover:opacity-100 transition-opacity">
            {language === 'sv' ? 'EN' : 'SV'}
          </button>
          <button 
            onClick={toggleTheme} 
            className="p-2 opacity-40 hover:opacity-100 transition-opacity"
            aria-label="Toggle dark mode"
          >
            {isDark ? <Sun size={20} /> : <Moon size={20} />}
          </button>

          <button 
            onClick={() => setIsMenuOpen(!isMenuOpen)} 
            className="flex items-center gap-4 group bg-black dark:bg-white text-white dark:text-black px-6 py-2.5 rounded-full hover:scale-105 transition-all"
          >
            <span className="text-[10px] font-bold tracking-[0.4em] uppercase">{isMenuOpen ? 'CLOSE' : 'MENU'}</span>
            <div className="flex flex-col gap-1 w-4">
              <span className={`h-px bg-current transition-all ${isMenuOpen ? 'rotate-45 translate-y-1' : ''}`} />
              <span className={`h-px bg-current transition-all ${isMenuOpen ? '-rotate-45 -translate-y-[1px]' : ''}`} />
            </div>
          </button>
        </div>
      </nav>

      <AnimatePresence>
        {isMenuOpen && (
          <motion.div 
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
            className="fixed inset-0 bg-white/98 dark:bg-black/98 backdrop-blur-3xl z-[105] flex flex-col items-center justify-center"
          >
            <div className="flex flex-col items-center gap-10 md:gap-16">
              <Link to="/" className="text-5xl md:text-[10vw] font-bold tracking-tighter hover:italic transition-all leading-none">{t('nav_start')}</Link>
              <Link to="/about" className="text-5xl md:text-[10vw] font-bold tracking-tighter hover:italic transition-all leading-none">{t('nav_about')}</Link>
              <Link to="/contact" className="text-5xl md:text-[10vw] font-bold tracking-tighter hover:italic transition-all leading-none">{t('nav_contact')}</Link>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
};

const BackgroundVideo = () => (
  <div className="fixed inset-0 z-[-1] overflow-hidden pointer-events-none opacity-[0.08] dark:opacity-[0.12]">
    <video
      autoPlay
      loop
      muted
      playsInline
      className="w-full h-full object-cover grayscale scale-110"
    >
      <source src="https://assets.mixkit.co/videos/preview/mixkit-slow-motion-of-abstract-smoke-in-the-air-40011-large.mp4" type="video/mp4" />
    </video>
    <div className="absolute inset-0 bg-white dark:bg-black mix-blend-overlay opacity-50" />
  </div>
);

const AppContent: React.FC = () => {
  const [isDark, setIsDark] = useState(true);

  useEffect(() => {
    const storedTheme = localStorage.getItem('theme');
    if (storedTheme === 'light') {
      setIsDark(false);
      document.documentElement.classList.remove('dark');
    } else {
      setIsDark(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  const toggleTheme = () => {
    const newDark = !isDark;
    setIsDark(newDark);
    document.documentElement.classList.toggle('dark');
    localStorage.setItem('theme', newDark ? 'dark' : 'light');
  };

  return (
    <Router>
      <ScrollToTop />
      <div className="min-h-screen selection:bg-black selection:text-white dark:selection:bg-white dark:selection:text-black transition-colors duration-500 font-sans relative overflow-x-hidden">
        <BackgroundVideo />
        <Navigation isDark={isDark} toggleTheme={toggleTheme} />

        <main className="relative z-10">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/about" element={<About />} />
            <Route path="/contact" element={<Contact />} />
            <Route path="/project/:id" element={<ProjectDetail />} /> 
          </Routes>
        </main>

        <Footer />
        <AIAssistant />
      </div>
    </Router>
  );
};

const App: React.FC = () => (
  <LanguageProvider>
    <AppContent />
  </LanguageProvider>
);

export default App;

